import os, sys

def clean(s):
    return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', ' ')

def q(step, ch, q_ur, q_en, ar, c_ur, c_en, w_ur, w_en, exp_ur, exp_en, book, d_ur, d_en, subj, cit):
    w_ur_s = ", ".join(['"' + clean(x) + '"' for x in w_ur])
    w_en_s = ", ".join(['"' + clean(x) + '"' for x in w_en])
    return f"""        RawQuestion(
            stepId = "{step}", chapterNum = {ch},
            questionUr = "{clean(q_ur)}",
            questionEn = "{clean(q_en)}",
            arabic = "{clean(ar)}",
            correctUr = "{clean(c_ur)}",
            correctEn = "{clean(c_en)}",
            wrongUr = listOf({w_ur_s}),
            wrongEn = listOf({w_en_s}),
            expUr = "{clean(exp_ur)}",
            expEn = "{clean(exp_en)}",
            bookName = "{clean(book)}", darjaUrdu = "{clean(d_ur)}", darjaEn = "{clean(d_en)}", subject = "{clean(subj)}", citation = "{clean(cit)}"
        )"""

# Let us generate 10 unique questions for every single one of the 40 chapters
